        var offset = vec3f(0.0);
        offset[axis] = lodScale[axis];
        let lo = floor((voxelPos - offset) / LOGICAL_BRICK_SIZE);
        let hi = floor((voxelPos + offset) / LOGICAL_BRICK_SIZE);
